endpoint.curlExample:
curl --location --request PUT 'https://api.onlinesales.ai/marketing/v1/advertiser/<advertiser_id>/sponsored_products/campaigns/<campaign_id>/product_sets' \
--header 'x-retailer-id: <ADD RETAILER-ID HERE>' \
--header 'x-token: <ADD YOUR AUTH TOKEN HERE>' \
--header 'Content-Type: application/json' \
--data '{
    "product_set": {
        "mode": "MANUAL",
        "products": [
            "product_id_1",
            "product_id_2"
        ]
    }
}'
